    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOAEN;
    RCC->APB2ENR |= RCC_APB2ENR_TIM1EN;

    /* 2. Configure PA8 in Alternate Function mode (AF6 = TIM1_CH1) */
    GPIOA->MODER &= ~(GPIO_MODER_MODE8_Msk);
    GPIOA->MODER |= (2U << GPIO_MODER_MODE8_Pos); /* AF mode (10b) */

    GPIOA->AFR[1] &= ~(0xFU << GPIO_AFRH_AFSEL8_Pos);
    GPIOA->AFR[1] |= (6U << GPIO_AFRH_AFSEL8_Pos); /* AF6: TIM1_CH1 */

    GPIOA->OSPEEDR |= (3U << GPIO_OSPEEDR_OSPEED8_Pos); /* Very high speed */
    GPIOA->PUPDR &= ~(GPIO_PUPDR_PUPD8_Msk);             /* No pull-up, no pull-down */

    /* 3. Configure TIM1 timebase for 20 kHz PWM */
    /* TIM1 kernel clock = 170 MHz */
    /* f_PWM = TIM1CLK / ((PSC + 1) * (ARR + 1)) = 170 MHz / (1 * 8500) = 20,000 Hz */
    TIM1->PSC = 0;
    TIM1->ARR = 8499;

    /* Duty cycle = CCR1 / (ARR + 1) = 2125 / 8500 = 25.0% */
    TIM1->CCR1 = 2125;

    /* 4. Configure Channel 1: PWM mode 1 (OC1M = 0110b), enable preload (OC1PE = 1) */
    TIM1->CCMR1 &= ~(TIM_CCMR1_OC1M_Msk | TIM_CCMR1_CC1S_Msk);
    TIM1->CCMR1 |= (6U << TIM_CCMR1_OC1M_Pos) | TIM_CCMR1_OC1PE;

    /* 5. Enable Channel 1 output (CC1E = 1), active-high polarity (CC1P = 0) */
    TIM1->CCER &= ~(TIM_CCER_CC1P | TIM_CCER_CC1NP);
    TIM1->CCER |= TIM_CCER_CC1E;

    /* 6. Enable Auto-reload preload (ARPE) */
    TIM1->CR1 |= TIM_CR1_ARPE;

    /* 7. Generate an update event to load preloaded registers into shadow registers */
    TIM1->EGR |= TIM_EGR_UG;

    /* 8. Enable Main Output (MOE) - required for advanced-control timer TIM1 */
    TIM1->BDTR |= TIM_BDTR_MOE;

    /* 9. Start the counter */
    TIM1->CR1 |= TIM_CR1_CEN;

    while (1) {
    }
}
